module LFSR (
    output reg  [3:0] out,
    input  wire       clk,
    input  wire       rst
);

    wire feedback;

    assign feedback = ~(out[3] ^ out[2]);

    always @(posedge clk) begin
        if (rst)
            out <= 4'b0000;
        else
            out <= {out[2:0], feedback};
    end

endmodule

