module freq_div (
    input  wire CLK_in,
    input  wire RST,
    output reg  CLK_50,
    output reg  CLK_10,
    output reg  CLK_1
);

    reg [2:0] cnt_10;
    reg [5:0] cnt_100;

    // 50 MHz: divide by 2
    always @(posedge CLK_in or posedge RST) begin
        if (RST)
            CLK_50 <= 1'b0;
        else
            CLK_50 <= ~CLK_50;
    end

    // 10 MHz: divide by 10 (toggle every 5 input cycles)
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_10 <= 1'b0;
            cnt_10 <= 3'd0;
        end
        else if (cnt_10 == 3'd4) begin
            CLK_10 <= ~CLK_10;
            cnt_10 <= 3'd0;
        end
        else begin
            cnt_10 <= cnt_10 + 3'd1;
        end
    end

    // 1 MHz: divide by 100 (toggle every 50 input cycles)
    always @(posedge CLK_in or posedge RST) begin
