            a_exponent <= {2'b00, a[30:23]} - 10'd127;
            a_mantissa <= {1'b0, a[22:0]};
            b_sign     <= b[31];
            b_exponent <= {2'b00, b[30:23]} - 10'd127;
            b_mantissa <= {1'b0, b[22:0]};
            counter    <= 3'd1;
