                    if (wave == 5'd0) begin
                        state <= 1'b0;
                        wave  <= wave;
                    end else begin
                        state <= 1'b1;
                        wave  <= wave - 5'd1;
                    end
                end
                default: begin
                    state <= 1'b0;
                    wave  <= 5'd0;
                end
            endcase
        end
    end

