module traffic_light (
    input  wire       rst_n,
    input  wire       clk,
    input  wire       pass_request,
    output wire [7:0] clock,
    output reg        red,
    output reg        yellow,
    output reg        green
);

    parameter idle     = 2'd0;
    parameter s1_red   = 2'd1;
    parameter s2_yellow= 2'd2;
    parameter s3_green = 2'd3;

    reg [7:0] cnt;
    reg [1:0] state;
    reg       p_red, p_yellow, p_green;

    // ---------------------------------------------------------------
    // State transition / next-lamp-value logic
    // ---------------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state    <= idle;
            p_red    <= 1'b0;
            p_yellow <= 1'b0;
            p_green  <= 1'b0;
        end
        else begin
            case (state)
                idle: begin
                    p_red    <= 1'b0;
                    p_yellow <= 1'b0;
                    p_green  <= 1'b0;
                    state    <= s1_red;
                end
                s1_red: begin
                    if (cnt == 8'd3) begin
                        state    <= s3_green;
                        p_red    <= 1'b0;
                        p_yellow <= 1'b0;
                        p_green  <= 1'b1;
                    end
                    else begin
                        state    <= s1_red;
                        p_red    <= 1'b1;
                        p_yellow <= 1'b0;
                        p_green  <= 1'b0;
                    end
                end
                s3_green: begin
                    if (cnt == 8'd3) begin
                        state    <= s2_yellow;
                        p_red    <= 1'b0;
                        p_yellow <= 1'b1;
                        p_green  <= 1'b0;
                    end
                    else begin
                        state    <= s3_green;
                        p_red    <= 1'b0;
                        p_yellow <= 1'b0;
                        p_green  <= 1'b1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 8'd3) begin
                        state    <= s1_red;
                        p_red    <= 1'b1;
                        p_yellow <= 1'b0;
                        p_green  <= 1'b0;
                    end
                    else begin
                        state    <= s2_yellow;
                        p_red    <= 1'b0;
                        p_yellow <= 1'b1;
                        p_green  <= 1'b0;
                    end
                end
                default: begin
                    state    <= idle;
                    p_red    <= 1'b0;
                    p_yellow <= 1'b0;
                    p_green  <= 1'b0;
                end
            endcase
        end
    end

    // ---------------------------------------------------------------
    // Counter logic
    // ---------------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            cnt <= 8'd10;
        else if (pass_request && green && (cnt > 8'd10))
            cnt <= 8'd10;
        else if (!green && p_green)
            cnt <= 8'd60;
        else if (!yellow && p_yellow)
            cnt <= 8'd5;
        else if (!red && p_red)
            cnt <= 8'd10;
        else
            cnt <= cnt - 8'd1;
    end

    assign clock = cnt;

    // ---------------------------------------------------------------
    // Output register logic
    // ---------------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red    <= 1'b0;
            yellow <= 1'b0;
            green  <= 1'b0;
        end
        else begin
            red    <= p_red;
            yellow <= p_yellow;
            green  <= p_green;
        end
    end

endmodule

